        CDefPointer<const CMaterialDef> pmaterial = hit_params.GetPHitMaterialDef();
        if (pmaterial.Get() && pmaterial->OnHitRumbleLevel != 0.0f && IS_THING_ALIVE(phitter) && phitter->GetType() == 2
